/**
 * The Banquet
 * -----------
 * King Ahasuerus feasts in Susa for a hundred and eighty days, and Queen Vashti refuses his summons. Stage: a Persian palace hall with blue and gold glazed bricks, a thousand couches, wine; the queen withdrawing from the far doorway; torchlight and marble.
 *
 * Palette 0x2a1a10 → 0x060402 · light: dawn · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./esther-kit.js.
 */

import { THREE, createScene, column, throne, vineyard, pillar, person } from './esther-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3065955150, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x20140c });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x1b110a });

    /* vineyard: posts, canopies, hanging fruit */
    vineyard(W, group, 0, 30, 40, 80, { leaf: 0x4f8a2e, berry: 0x1d120b });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x372215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.37, s: 1.15 });

    return W.finish();
}

export default { build };
